// Exact quartic certificate: unit relations.
#include "s61_binary_deeper_quartic_field_20261101.hpp"
void elim(Row&x,const Rat&h,const Row&b){for(auto&[j,v]:b){Rat z=sub(x[j],mul(h,v));if(z.zero())x.erase(j);else x[j]=std::move(z);}}
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);flint_set_num_threads(2);{ifstream in(argv[1]);int nr,nc;in>>nr>>nc;vector<Row>A(nr),C(nr),B,BC;vector<int>pivs,chosen;for(int i=0;i<nr;i++){int n;in>>n;for(int j=0;j<n;j++){int k;in>>k;Rat c;readpoly(in,c.n);readpoly(in,c.d);c.reduce();A[i].emplace(k,std::move(c));}Rat one;fmpq_mpoly_one(one.n,ctx);C[i].emplace(i,std::move(one));}
while(B.size()<114){int best=-1,col=-1;long score=0;for(int i=0;i<nr;i++)for(auto&[j,v]:A[i]){long z=fmpq_mpoly_length(v.n,ctx)+fmpq_mpoly_length(v.d,ctx);if(best<0||z<score){score=z;best=i;col=j;}}assert(best>=0);Row row=std::move(A[best]),cr=std::move(C[best]);Rat c=row[col];assert(fmpq_mpoly_is_fmpq(c.n,ctx)&&fmpq_mpoly_is_fmpq(c.d,ctx));for(auto&[j,v]:row)v=divi(v,c);for(auto&[j,v]:cr)v=divi(v,c);for(int i=0;i<nr;i++){auto it=A[i].find(col);if(it==A[i].end())continue;Rat h=it->second;elim(A[i],h,row);elim(C[i],h,cr);}pivs.push_back(col);chosen.push_back(best);B.push_back(std::move(row));BC.push_back(std::move(cr));}
vector<int>zero,relations;for(int i=0;i<nr;i++)if(A[i].empty()){zero.push_back(i);if(!C[i].empty())relations.push_back(i);}cerr<<"ZERO "<<zero.size()<<" RELATIONS "<<relations.size()<<"\n";assert(zero.size()==200&&relations.size()==86);ofstream out(argv[2]);assert(out);out<<relations.size()<<" "<<nr<<"\n";for(int i:relations){out<<i<<" "<<C[i].size()<<"\n";for(auto&[j,c]:C[i]){out<<j<<"\n";writepoly(out,c.n);writepoly(out,c.d);}}ofstream info(string(argv[2])+".info");assert(info);for(int i:zero)info<<i<<" ";info<<"\n";for(int i:chosen)info<<i<<" ";info<<"\n";for(int i:pivs)info<<i<<" ";info<<"\n";}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
